console.log('Tổng số từ vựng được tạo:', words.length);

// Thêm Byte Order Mark (BOM) \uFEFF để khi người dùng mở file CSV bằng Microsoft Excel không bị lỗi font chữ tiếng Việt
const BOM = '\uFEFF';
const header = 'word,meaning,topic,level,word_type,example\n';

const escapeCsvField = (field) => {
  if (field === null || field === undefined) return '""';
  const str = String(field);
  return '"' + str.replace(/"/g, '""') + '"';
};

const rows = words.map(item => {
  return [
    escapeCsvField(item.word),
    escapeCsvField(item.meaning),
    escapeCsvField(item.topic),
    escapeCsvField(item.level),
    escapeCsvField(item.word_type),
    escapeCsvField(item.example)
  ].join(',');
}).join('\n');

const outputPath = path.join(__dirname, 'arena_words_seed.csv');
fs.writeFileSync(outputPath, BOM + header + rows, 'utf8');
console.log('Đã tạo thành công file CSV tại:', outputPath);
